105	
106	    /**
107	     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED} event.
108	     * Shared across all creates so the events can be totally ordered independently of timestamps.
109	     */
110	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
111	
112	    /**
113	     * Serializes structured audit events to compact JSON. Configured once and reused; it is thread-safe.
114	     */
115	    private static final ObjectMapper AUDIT_EVENT_MAPPER = JsonMapper.builder().build();
116	
117	    /**
