177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
180	        String idempotencyKey = idempotencyKey();
181	        if (idempotencyKey != null) {
182	            Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
183	            if (existingId != null) {
184	                Owner existing = this.clinicService.findOwnerById(existingId);
185	                if (existing != null) {
186	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
187	                }
188	            }
189	        }
190	        rejectMissingOrBlankFields(ownerFieldsDto);
191	        HttpHeaders headers = new HttpHeaders();
192	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
193	        applyAddress(owner);
194	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
195	        owner.setEmail(normalizeEmail(owner.getEmail()));
196	        validatePostcode(owner.getPostcode(), owner.getCity());
197	        rejectFutureRegistrationDate(owner.getRegistrationDate());
198	        if (owner.getRegistrationDate() == null) {
199	            owner.setRegistrationDate(LocalDate.now());
200	        }
201	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
202	        rejectDailyLimitReached(owner.getRegistrationDate());
203	        rejectCityAtCapacity(owner.getCity());
204	        owner.setHouseholdId(computeHouseholdId(owner));
205	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
206	        rejectDuplicateIdentity(owner);
207	        assignPossibleDuplicate(owner, sharesHousehold);
208	        owner.setCustomerCode(generateCustomerCode(owner));
209	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
210	        owner.setHouseholdSize(countHouseholdSize(owner.getHouseholdId()));
211	        owner.setMembershipLevel(computeMembershipLevel(owner));
212	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
213	        owner.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
214	        this.clinicService.saveOwner(owner);
215	        if (idempotencyKey != null) {
216	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
217	        }
218	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
219	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
220	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
221	            ownerDto.getMembershipNumber());
222	        emitOwnerCreatedEvent(owner, ownerDto);
223	        headers.setLocation(UriComponentsBuilder.newInstance()
224	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
225	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
226	    }
