323	    /**
324	     * Emits an immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger, alongside the
325	     * human-readable audit line. The event is a JSON object
326	     * {@code {seq, ownerId, customerCode, membershipLevel, event}} where {@code seq} is a process-wide,
327	     * monotonically increasing sequence number across all creates.
328	     *
329	     * <p>The {@code customerCode} field carries the owner's <em>current primary identifier</em> — see
330	     * {@link #primaryIdentifier(Owner)}. Today that is the {@code customerCode}; when the primary identifier
331	     * is later unified into the member id, the event will carry the member id instead without any change here.
332	     *
333	     * @param owner    the freshly persisted owner
334	     * @param ownerDto its DTO projection, used for the derived membership level
335	     */
336	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
337	        Map<String, Object> event = new LinkedHashMap<>();
338	        event.put("seq", OWNER_CREATED_SEQUENCE.incrementAndGet());
339	        event.put("ownerId", owner.getId());
340	        event.put("customerCode", primaryIdentifier(owner));
341	        event.put("membershipLevel", ownerDto.getMembershipLevel());
342	        event.put("event", "OWNER_CREATED");
343	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
344	    }
