346	    /**
347	     * Returns the owner's current primary identifier, which structured audit events must carry. This is the
348	     * single point that decides which field is primary: today the {@code customerCode}, and whatever replaces
349	     * it later (e.g. once the customer code is unified into the member id).
350	     *
351	     * @param owner the owner whose primary identifier is required
352	     * @return the current primary identifier
353	     */
354	    private String primaryIdentifier(Owner owner) {
355	        return owner.getCustomerCode();
356	    }
