358	    /**
359	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
360	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
361	     *
362	     * @param fields the submitted owner fields
363	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
364	     *                                        {@code null} or blank, or if the owner supplies no address
365	     *                                        in either form (a blank structured {@code addressLine1} and a
366	     *                                        blank flat {@code address}, each measured after normalization)
367	     */
368	    /**
369	     * Reads the client-supplied {@code Idempotency-Key} header for the current create request, if any.
370	     *
371	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
372	     */
373	    private String idempotencyKey() {
374	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
375	        if (key == null || key.isBlank()) {
376	            return null;
377	        }
378	        return key.strip();
379	    }
