381	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
382	        List<String> missing = new ArrayList<>();
383	        if (isBlank(fields.getFirstName())) {
384	            missing.add("firstName");
385	        }
386	        if (isBlank(fields.getLastName())) {
387	            missing.add("lastName");
388	        }
389	        boolean hasStructuredAddress = !isBlank(normalizeAddress(fields.getAddressLine1()));
390	        boolean hasFlatAddress = !isBlank(normalizeAddress(fields.getAddress()));
391	        if (!hasStructuredAddress && !hasFlatAddress) {
392	            missing.add("address");
393	        }
394	        if (isBlank(fields.getCity())) {
395	            missing.add("city");
396	        }
397	        if (isBlank(fields.getTelephone())) {
398	            missing.add("telephone");
399	        }
400	        if (!missing.isEmpty()) {
401	            throw new RequiredFieldsMissingException(missing);
402	        }
403	    }
