409	    /**
410	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
411	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
412	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
413	     */
414	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
415	        "NSW", new int[] {2000, 2099},
416	        "VIC", new int[] {3000, 3099},
417	        "QLD", new int[] {4000, 4099});
418	
419	    /**
420	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
421	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
422	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
423	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
424	     *
425	     * @param postcode the submitted postcode, or {@code null} when omitted
426	     * @param city the owner's city, used to derive the region whose range constrains the postcode
427	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
428	     *                                  city's region
429	     */
430	    private void validatePostcode(String postcode, String city) {
431	        if (postcode == null) {
432	            return;
433	        }
434	        if (!postcode.matches("[0-9]{4}")) {
435	            throw new InvalidPostcodeException(postcode);
436	        }
437	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
438	        if (range == null) {
439	            return;
440	        }
441	        int value = Integer.parseInt(postcode);
442	        if (value < range[0] || value > range[1]) {
443	            throw new InvalidPostcodeException(postcode);
444	        }
445	    }
