447	    /**
448	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
449	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
450	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
451	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
452	     * <p>
453	     * Where a per-country rule is defined the national-number length is validated against the country
454	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
455	     * requires exactly 10.
456	     *
457	     * @param telephone the raw telephone value from the request
458	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
459	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
460	     */
461	    private String normalizeTelephone(String telephone) {
462	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
463	        String digits;
464	        if (cleaned.startsWith("+")) {
465	            digits = cleaned.substring(1);
466	        } else {
467	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
468	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
469	            digits = "61" + national;
470	        }
471	        if (!digits.matches("[0-9]{8,15}")) {
472	            throw new InvalidTelephoneException(cleaned);
473	        }
474	        // Validate the national-number length against the country code where a rule is defined.
475	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
476	            throw new InvalidTelephoneException(cleaned);
477	        }
478	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
479	            throw new InvalidTelephoneException(cleaned);
480	        }
481	        return "+" + digits;
482	    }
