484	    /**
485	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
486	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
487	     * lower-cased.
488	     *
489	     * @param email the raw email value from the request, or {@code null} if omitted
490	     * @return the lower-cased email, or {@code null} if none was supplied
491	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
492	     */
493	    private String normalizeEmail(String email) {
494	        if (email == null) {
495	            return null;
496	        }
497	        String trimmed = email.strip();
498	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
499	            throw new InvalidEmailException(email);
500	        }
501	        String normalized = trimmed.toLowerCase(Locale.ROOT);
502	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
503	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
504	            throw new DisposableEmailDomainException(domain);
505	        }
506	        return normalized;
507	    }
