509	    /**
510	     * Applies the owner's address in whichever form the request supplied, preferring the structured
511	     * fields. When a non-blank {@code addressLine1} is present, {@code addressLine1} and (when present)
512	     * {@code addressLine2} are normalized in place and the flat {@code address} is set to the composed
513	     * value: the normalized {@code addressLine1}, with a single space and the normalized
514	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the structured
515	     * lines are cleared and the flat {@code address} is normalized on its own, keeping the earlier
516	     * flat-address contract backward-compatible.
517	     *
518	     * @param owner the owner being created, mapped straight from the request
519	     */
520	    private void applyAddress(Owner owner) {
521	        if (!isBlank(owner.getAddressLine1())) {
522	            String line1 = normalizeAddress(owner.getAddressLine1());
523	            owner.setAddressLine1(line1);
524	            String composed = line1;
525	            if (!isBlank(owner.getAddressLine2())) {
526	                String line2 = normalizeAddress(owner.getAddressLine2());
527	                owner.setAddressLine2(line2);
528	                composed = line1 + " " + line2;
529	            } else {
530	                owner.setAddressLine2(null);
531	            }
532	            owner.setAddress(composed);
533	        } else {
534	            owner.setAddressLine1(null);
535	            owner.setAddressLine2(null);
536	            owner.setAddress(normalizeAddress(owner.getAddress()));
537	        }
538	    }
539	
540	    /**
541	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
542	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
543	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
544	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
545	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
546	     *
547	     * @param address the raw address value from the request (may be {@code null})
548	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
549	     */
550	    private String normalizeAddress(String address) {
551	        if (address == null) {
552	            return "";
553	        }
554	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
555	        if (collapsed.isEmpty()) {
556	            return "";
557	        }
558	        String[] tokens = collapsed.split(" ");
559	        StringBuilder sb = new StringBuilder(collapsed.length());
560	        for (int i = 0; i < tokens.length; i++) {
561	            if (i > 0) {
562	                sb.append(' ');
563	            }
564	            sb.append(expandAddressAbbreviation(tokens[i]));
565	        }
566	        return sb.toString();
567	    }
568	
569	    /**
570	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
571	     * returns the token unchanged when it is not a recognised abbreviation.
572	     *
573	     * @param token an upper-cased whole-word address token
574	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
575	     */
576	    private String expandAddressAbbreviation(String token) {
577	        return switch (token) {
578	            case "ST" -> "STREET";
579	            case "RD" -> "ROAD";
580	            case "AVE" -> "AVENUE";
581	            default -> token;
582	        };
583	    }
