585	    /**
586	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
587	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
588	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
589	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
590	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}).
591	     * <p>
592	     * Should the computed code collide with an existing owner's {@code customerCode}, it is de-duplicated
593	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not already
594	     * held by any existing owner; the de-duplicated code is returned.
595	     *
596	     * @param owner the owner being created, with normalized telephone and postcode already set
597	     * @return the assigned, collision-free customer code
598	     */
599	    private String generateCustomerCode(Owner owner) {
600	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
601	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
602	            .substring(0, 8).toUpperCase(Locale.ROOT);
603	        String base = region + "-" + hash8;
604	        Set<String> existing = this.clinicService.findAllOwners().stream()
605	            .map(Owner::getCustomerCode)
606	            .filter(code -> code != null)
607	            .collect(java.util.stream.Collectors.toSet());
608	        if (!existing.contains(base)) {
609	            return base;
610	        }
611	        int n = 2;
612	        while (existing.contains(base + "-" + n)) {
613	            n++;
614	        }
615	        return base + "-" + n;
616	    }
617	
618	    /**
619	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
620	     *
621	     * @param value the value to hash
622	     * @return the 64-character lower-case hex SHA-256 digest
623	     */
624	    private String sha256Hex(String value) {
625	        try {
626	            byte[] digest = MessageDigest.getInstance("SHA-256")
627	                .digest(value.getBytes(StandardCharsets.UTF_8));
628	            StringBuilder sb = new StringBuilder(digest.length * 2);
629	            for (byte b : digest) {
630	                sb.append(String.format("%02x", b));
631	            }
632	            return sb.toString();
633	        } catch (NoSuchAlgorithmException e) {
634	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
635	        }
636	    }
