638	    /**
639	     * Counts how many existing owners already share the given first name and last name, compared
640	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
641	     * owner being created.
642	     *
643	     * @param firstName the first name of the owner being created
644	     * @param lastName the last name of the owner being created
645	     * @return the number of existing owners with the same first and last name (case-insensitively)
646	     */
647	    private int countNamesakes(String firstName, String lastName) {
648	        return (int) this.clinicService.findAllOwners().stream()
649	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
650	                && lastName.equalsIgnoreCase(existing.getLastName()))
651	            .count();
652	    }
