654	    /**
655	     * Computes the size of the owner's household: the number of existing owners already sharing the given
656	     * {@code householdId} plus the owner being created itself. The existing count is taken before the new
657	     * owner is persisted, so adding one for the owner yields the household's total membership including it
658	     * (e.g. two existing members give a household size of 3 for the third member). Households are keyed on
659	     * the deterministic {@code householdId} (derived from last name and postcode).
660	     *
661	     * @param householdId the computed household identifier of the owner being created
662	     * @return the household size including the owner being created (at least 1)
663	     */
664	    private int countHouseholdSize(String householdId) {
665	        long existing = this.clinicService.findAllOwners().stream()
666	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
667	            .count();
668	        return (int) existing + 1;
669	    }
670	
671	    /**
672	     * Computes the membership level assigned to a newly created owner, applying the household level ceiling.
673	     * The owner's own (uncapped) level cannot exceed one above the current maximum membership level among
674	     * their existing household members, where every level is measured against the household's current size
675	     * (the owner's just-computed {@code householdSize}). When the owner has no existing household member the
676	     * ceiling does not apply and the uncapped level is returned. The count is taken before the new owner is
677	     * persisted, so it excludes the owner being created; the existing members share the deterministic
678	     * {@code householdId} and any soft-deleted owner is ignored.
679	     *
680	     * @param owner the owner being created, with its {@code householdId} and {@code householdSize} already set
681	     * @return the owner's membership level, capped at one above the existing household maximum
682	     */
683	    private Integer computeMembershipLevel(Owner owner) {
684	        Integer householdSize = owner.getHouseholdSize();
685	        Integer ownLevel = this.ownerMapper.membershipLevelForHouseholdSize(owner, householdSize);
686	        String householdId = owner.getHouseholdId();
687	        int maxExisting = this.clinicService.findAllOwners().stream()
688	            .filter(existing -> !isDeleted(existing))
689	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
690	            .mapToInt(existing -> this.ownerMapper.membershipLevelForHouseholdSize(existing, householdSize))
691	            .max()
692	            .orElse(-1);
693	        if (maxExisting < 0) {
694	            return ownLevel;
695	        }
696	        return Math.min(ownLevel, maxExisting + 1);
697	    }
698	
699	    /**
700	     * The maximum number of owners permitted in a single city. A create request whose city already
701	     * holds this many owners is rejected.
702	     */
703	    private static final int CITY_OWNER_LIMIT = 50;
704	
705	    /**
706	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
707	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
708	     * differing only in the casing of their city share one capacity pool. The count is taken before the
709	     * new owner is persisted, so it excludes the owner being created.
710	     *
711	     * @param city the city of the owner being created
712	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
713	     */
714	    private void rejectCityAtCapacity(String city) {
715	        long existing = this.clinicService.findAllOwners().stream()
716	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
717	            .count();
718	        if (existing >= CITY_OWNER_LIMIT) {
719	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
720	        }
721	    }
722	
723	    /**
724	     * The number of owners a city must already hold before a create request is flagged as approaching the
725	     * per-city capacity limit. Once the count reaches this threshold (but is still below
726	     * {@link #CITY_OWNER_LIMIT}) the created owner carries {@code capacityWarning = true}.
727	     */
728	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
729	
730	    /**
731	     * Reports whether the given city is approaching its per-city capacity limit, i.e. already holds between
732	     * {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_LIMIT} (exclusive) owners. Cities are
733	     * matched case-insensitively, mirroring {@link #rejectCityAtCapacity(String)}. The count is taken before
734	     * the new owner is persisted, so it excludes the owner being created.
735	     *
736	     * @param city the city of the owner being created
737	     * @return {@code true} when the city already holds 40 to 49 owners inclusive, otherwise {@code false}
738	     */
739	    private boolean isCityApproachingCapacity(String city) {
740	        long existing = this.clinicService.findAllOwners().stream()
741	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
742	            .count();
743	        return existing >= CITY_CAPACITY_WARNING_THRESHOLD && existing < CITY_OWNER_LIMIT;
744	    }
745	
746	    /**
747	     * The maximum number of owners permitted to be created in a single day. A create request whose
748	     * registration date already holds this many owners is rejected.
749	     */
750	    private static final int DAILY_OWNER_LIMIT = 100;
751	
752	    /**
753	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
754	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
755	     * persisted, so it excludes the owner being created.
756	     *
757	     * @param registrationDate the registration date of the owner being created
758	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
759	     */
760	    /**
761	     * The fixed list of public holidays that are not treated as business days. A registration date that
762	     * lands on one of these dates is rolled forward, just as a weekend is.
763	     */
764	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
765	        LocalDate.of(2026, 1, 1),
766	        LocalDate.of(2026, 1, 26),
767	        LocalDate.of(2026, 4, 25),
768	        LocalDate.of(2026, 12, 25),
769	        LocalDate.of(2026, 12, 28));
770	
771	    /**
772	     * Adjusts an effective registration date so that it always falls on a business day. When the given
773	     * date is a Saturday, a Sunday or a listed public holiday it is rolled forward one day at a time until
774	     * it reaches the next non-holiday business day; a weekday that is not a holiday is returned unchanged.
775	     * This applies equally to a date supplied in the request and to a date defaulted to the server date, and
776	     * the adjusted value is what becomes the owner's {@code registrationDate}, so every value derived from it
777	     * (the membership number's year segment, the daily create-limit count) uses the business-day-adjusted
778	     * date.
779	     *
780	     * @param date the effective registration date, supplied or defaulted
781	     * @return the same date when it is a business day, otherwise the next non-holiday business day
782	     */
783	    private LocalDate rollToBusinessDay(LocalDate date) {
784	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
785	            date = date.plusDays(1);
786	        }
787	        return date;
788	    }
789	
790	    private boolean isWeekend(LocalDate date) {
791	        DayOfWeek day = date.getDayOfWeek();
792	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
793	    }
794	
795	    /**
796	     * The number of owners that must already exist for a given day before a further create is flagged as a
797	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
798	     * the created owner carries {@code bulkSignupWarning = true}.
799	     */
800	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
801	
802	    /**
803	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
804	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
805	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
806	     * the daily create-limit rule's accumulation path.
807	     *
808	     * @param registrationDate the registration date of the owner being created
809	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
810	     */
811	    private boolean isBulkSignupDay(LocalDate registrationDate) {
812	        long existing = this.clinicService.findAllOwners().stream()
813	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
814	            .count();
815	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
816	    }
817	
818	    /**
819	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
820	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
821	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
822	     * made against the supplied value before any business-day adjustment.
823	     *
824	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
825	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
826	     */
827	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
828	        if (registrationDate == null) {
829	            return;
830	        }
831	        LocalDate today = LocalDate.now();
832	        if (registrationDate.isAfter(today)) {
833	            throw new FutureRegistrationDateException(registrationDate, today);
834	        }
835	    }
836	
837	    private void rejectDailyLimitReached(LocalDate registrationDate) {
838	        long existing = this.clinicService.findAllOwners().stream()
839	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
840	            .count();
841	        if (existing >= DAILY_OWNER_LIMIT) {
842	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
843	        }
844	    }
845	
846	    /**
847	     * Rejects a create request whose owner collides with an existing owner on the single derived
848	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
849	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
850	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
851	     * household (same {@code householdId}) with different telephones have different keys and are both
852	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} has already
853	     * been computed (deterministically from the last name and postcode) before this check runs, so the
854	     * key compared here is the same one that is later returned.
855	     *
856	     * @param owner the owner being created, with normalized fields and its computed {@code householdId} set
857	     * @throws DuplicateIdentityException if an existing owner has the same identity key
858	     */
859	    private void rejectDuplicateIdentity(Owner owner) {
860	        String key = identityKey(owner);
861	        boolean taken = this.clinicService.findAllOwners().stream()
862	            .filter(existing -> !isDeleted(existing))
863	            .anyMatch(existing -> key.equals(identityKey(existing)));
864	        if (taken) {
865	            throw new DuplicateIdentityException(key);
866	        }
867	    }
868	
869	    /**
870	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
871	     * while not a hard {@code identityKey} duplicate (that stronger check has already run, so its whole
872	     * identity key differs), shares this owner's last-name {@link #soundex(String) soundex} and exact
873	     * postcode. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
874	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
875	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
876	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
877	     * <p>
878	     * A declared household member ({@code sharesHousehold}) is never flagged: it is a known household member
879	     * rather than a suspected duplicate.
880	     *
881	     * @param owner the owner being created, with normalized telephone and validated postcode already set
882	     * @param sharesHousehold whether the create declared the owner a household member
883	     */
884	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
885	        Integer matchId = null;
886	        if (!sharesHousehold && owner.getPostcode() != null) {
887	            String key = identityKey(owner);
888	            String soundex = soundex(owner.getLastName());
889	            matchId = this.clinicService.findAllOwners().stream()
890	                .filter(existing -> !isDeleted(existing))
891	                .filter(existing -> soundex.equals(soundex(existing.getLastName()))
892	                    && owner.getPostcode().equals(existing.getPostcode())
893	                    && !key.equals(identityKey(existing)))
894	                .map(Owner::getId)
895	                .filter(id -> id != null)
896	                .min(Comparator.naturalOrder())
897	                .orElse(null);
898	        }
899	        owner.setPossibleDuplicate(matchId != null);
900	        owner.setPossibleDuplicateOf(matchId);
901	    }
902	
903	    /**
904	     * Whether an existing owner has been soft-deleted. A soft-deleted owner is retained and still
905	     * readable, but is ignored by the create endpoint's duplicate and identity checks.
906	     *
907	     * @param owner an existing owner
908	     * @return {@code true} when the owner is flagged deleted, otherwise {@code false}
909	     */
910	    private boolean isDeleted(Owner owner) {
911	        return Boolean.TRUE.equals(owner.getDeleted());
912	    }
913	
914	    /**
915	     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 digest of the normalized
916	     * telephone, the lower-cased email (or an empty string when absent) and the {@link #soundex(String)
917	     * soundex} of the last name, joined by {@code '|'} in that order before hashing (e.g. the digest of
918	     * {@code '+61412345678||F650'}). Telephone and email are stored already normalized, so the stored
919	     * values are used directly. This single 64-hex key is what duplicate detection compares.
920	     *
921	     * @param owner the owner whose identity key is being derived
922	     * @return the owner's identity key, a 64-character lower-case hex SHA-256 digest
923	     */
924	    private String identityKey(Owner owner) {
925	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
926	        String email = owner.getEmail() == null ? "" : owner.getEmail();
927	        String soundex = soundex(owner.getLastName());
928	        return sha256Hex(telephone + "|" + email + "|" + soundex);
929	    }
930	
931	    /**
932	     * Computes the American Soundex code of the given value: the retained (upper-cased) first letter
933	     * followed by three digits derived from the remaining consonants, right-padded with zeros or
934	     * truncated to length four. Non-letters are ignored; adjacent letters mapping to the same digit are
935	     * coded once (bridged across {@code 'H'}/{@code 'W'}), and vowels reset the run so a repeated code
936	     * separated by a vowel is coded twice. A {@code null} or letter-free value yields an empty string.
937	     *
938	     * @param value the value (typically a last name) to encode
939	     * @return the four-character Soundex code, or an empty string when there are no letters
940	     */
941	    private String soundex(String value) {
942	        if (value == null) {
943	            return "";
944	        }
945	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
946	        if (letters.isEmpty()) {
947	            return "";
948	        }
949	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
950	        char prev = soundexDigit(letters.charAt(0));
951	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
952	            char c = letters.charAt(i);
953	            if (c == 'H' || c == 'W') {
954	                continue;
955	            }
956	            char digit = soundexDigit(c);
957	            if (digit != '0' && digit != prev) {
958	                code.append(digit);
959	            }
960	            prev = digit;
961	        }
962	        while (code.length() < 4) {
963	            code.append('0');
964	        }
965	        return code.toString();
966	    }
967	
968	    /**
969	     * Maps a single upper-case letter to its Soundex digit ({@code '1'}-{@code '6'}), or {@code '0'} for
970	     * vowels and the non-coding letters {@code H}/{@code W}/{@code Y}.
971	     *
972	     * @param c an upper-case letter
973	     * @return the letter's Soundex digit
974	     */
975	    private char soundexDigit(char c) {
976	        return switch (c) {
977	            case 'B', 'F', 'P', 'V' -> '1';
978	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
979	            case 'D', 'T' -> '3';
980	            case 'L' -> '4';
981	            case 'M', 'N' -> '5';
982	            case 'R' -> '6';
983	            default -> '0';
984	        };
985	    }
986	
987	    /**
988	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
989	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
990	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
991	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
992	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
993	     * whether or not {@code sharesHousehold} was requested.
994	     *
995	     * @param owner the owner being created, with its validated postcode already set
996	     * @return the deterministic household identifier
997	     */
998	    private String computeHouseholdId(Owner owner) {
999	        String normalizedLastName = normalizeForComparison(owner.getLastName());
1000	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
1001	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
1002	    }
1003	
1004	    /**
1005	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
1006	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
1007	     * lower-cased.
1008	     *
1009	     * @param value the raw value to normalize (may be {@code null})
1010	     * @return the normalized value, or an empty string when {@code value} is {@code null}
1011	     */
1012	    private String normalizeForComparison(String value) {
1013	        if (value == null) {
1014	            return "";
1015	        }
1016	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1017	    }
1018	}
