310	        String email = owner.getEmail() == null ? "" : owner.getEmail();
311	        String soundex = soundex(owner.getLastName());
312	        return sha256Hex(telephone + "|" + email + "|" + soundex);
313	    }
314	
315	    /**
316	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
317	     *
318	     * @param value the value to hash
319	     * @return the 64-character lower-case hex SHA-256 digest
320	     */
321	    private String sha256Hex(String value) {
322	        try {
323	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
324	            StringBuilder sb = new StringBuilder(digest.length * 2);
325	            for (byte b : digest) {
326	                sb.append(String.format("%02x", b));
327	            }
328	            return sb.toString();
329	        }
330	        catch (NoSuchAlgorithmException e) {
331	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
332	        }
333	    }
334	
335	    /**
336	     * Computes the American Soundex code of the given value: the retained (upper-cased) first letter
337	     * followed by three digits derived from the remaining consonants, right-padded with zeros or truncated
338	     * to length four. Non-letters are ignored; adjacent letters mapping to the same digit are coded once
339	     * (bridged across {@code 'H'}/{@code 'W'}), and vowels reset the run. A {@code null} or letter-free
340	     * value yields an empty string. This matches the create endpoint's soundex so identity keys agree.
341	     *
342	     * @param value the value (typically a last name) to encode
343	     * @return the four-character Soundex code, or an empty string when there are no letters
344	     */
345	    private String soundex(String value) {
346	        if (value == null) {
347	            return "";
348	        }
349	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
350	        if (letters.isEmpty()) {
351	            return "";
352	        }
353	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
354	        char prev = soundexDigit(letters.charAt(0));
355	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
356	            char c = letters.charAt(i);
357	            if (c == 'H' || c == 'W') {
358	                continue;
359	            }
360	            char digit = soundexDigit(c);
361	            if (digit != '0' && digit != prev) {
362	                code.append(digit);
363	            }
364	            prev = digit;
365	        }
366	        while (code.length() < 4) {
367	            code.append('0');
368	        }
369	        return code.toString();
370	    }
371	
372	    private char soundexDigit(char c) {
373	        return switch (c) {
374	            case 'B', 'F', 'P', 'V' -> '1';
375	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
376	            case 'D', 'T' -> '3';
377	            case 'L' -> '4';
378	            case 'M', 'N' -> '5';
379	            case 'R' -> '6';
380	            default -> '0';
381	        };
382	    }
383	
384	    /**
385	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
386	     * national digits grouped in threes from the left (e.g. {@code '+61412345678'} becomes
387	     * {@code '+61 412 345 678'}). The raw {@code telephone} is left untouched in E.164 form. Values that are
388	     * {@code null} or not in E.164 form (no leading {@code '+'}) are returned unchanged.
389	     * <p>
390	     * The country code is split off using the codes the application recognises: {@code '+1'} (NANP) is a
391	     * single digit and any other number is assumed to carry the default {@code '+61'}-style two-digit code.
392	     *
393	     * @param owner the owner whose telephone is being formatted
394	     * @return the human-formatted telephone, or the raw value when it is {@code null} or not E.164
395	     */
396	    protected String telephoneDisplay(Owner owner) {
397	        String telephone = owner.getTelephone();
398	        if (telephone == null || !telephone.startsWith("+")) {
399	            return telephone;
400	        }
401	        String digits = telephone.substring(1);
402	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
403	        if (digits.length() <= countryCodeLength) {
404	            return telephone;
405	        }
406	        String countryCode = digits.substring(0, countryCodeLength);
407	        String national = digits.substring(countryCodeLength);
408	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
409	        for (int i = 0; i < national.length(); i++) {
410	            if (i % 3 == 0) {
411	                grouped.append(' ');
412	            }
413	            grouped.append(national.charAt(i));
414	        }
415	        return grouped.toString();
416	    }
417	
418	    /**
419	     * Composes the owner's salutation: the {@code title}, a single space and the last name (e.g.
420	     * {@code 'DR Franklin'}) when a non-blank {@code title} was supplied, or just the last name when no
421	     * title was given.
422	     *
423	     * @param owner the owner whose salutation is being composed
424	     * @return {@code '<title> <lastName>'} when a title is present, otherwise the last name alone
425	     */
426	    protected String salutation(Owner owner) {
427	        String title = owner.getTitle();
428	        if (title == null || title.isBlank()) {
429	            return owner.getLastName();
430	        }
431	        return title + " " + owner.getLastName();
432	    }
433	
434	    /**
435	     * Derives an owner's {@code selfLink}: the canonical relative URL of the owner resource, formatted
436	     * {@code '/api/owners/<id>'} from the owner's id. Returns {@code null} when the owner has no id yet.
437	     *
438	     * @param owner the owner whose self link is being derived
439	     * @return the owner's self link, or {@code null} when the owner has no id
440	     */
441	    protected String selfLink(Owner owner) {
442	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
443	    }
444	
445	    /**
446	     * Derives an owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
447	     * {@code 'PREMIUM'} when the owner's effective membership level is 3 or more, otherwise
448	     * {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality is a known region (NSW,
449	     * VIC or QLD), otherwise {@code 'REGIONAL'}. The result is one of {@code 'PREMIUM_METRO'},
450	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}.
451	     *
452	     * @param owner the owner whose segment is being derived
453	     * @return the owner's segment as {@code '<TIER>_<AREA>'}
454	     */
455	    protected String ownerSegment(Owner owner) {
456	        Integer level = owner.getMembershipLevel() != null ? owner.getMembershipLevel() : membershipLevel(owner);
457	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
458	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
459	        boolean known = "NSW".equals(region) || "VIC".equals(region) || "QLD".equals(region);
460	        String area = known ? "METRO" : "REGIONAL";
461	        return tier + "_" + area;
462	    }
463	
464	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
465	        OwnerPageDto ownerPageDto = new OwnerPageDto();
466	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
467	        ownerPageDto.setPage(ownerPage.getNumber());
468	        ownerPageDto.setSize(ownerPage.getSize());
469	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
470	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
471	        return ownerPageDto;
472	    }
473	}
